('advanced-native-278', '["phrase"]'::jsonb, '{"advanced-native-278-v1-audio":{"type":"mc","answers":["It was close enough to pick up without leaving the desk."],"options":["It was close enough to pick up without leaving the desk.","It was stored elsewhere and brought in only after the task.","It was already held in the speaker’s hand throughout the task.","It was visible on a shelf across the room but too far to touch."]},"advanced-native-278-v2-reply":{"type":"mc","answers":["I wanted the card within arm’s reach.","That position made it easy to consult during the task.","I could reach it quickly when I needed a reminder.","I could pick it up without leaving the desk."],"options":["I wanted the card within arm’s reach.","That position made it easy to consult during the task.","I could reach it quickly when I needed a reminder.","I could pick it up without leaving the desk."]},"advanced-native-278-v1-scene":{"type":"mc","answers":["The dictionary is beside your elbow on the desk."],"options":["The dictionary is beside your elbow on the desk.","The dictionary is visible on the far wall shelf but requires you to stand and cross the room.","The dictionary stays in a cupboard in the next room."]},"advanced-native-278-v1-contrast":{"type":"mc","answers":["Any object in the same room qualifies, even if the person must walk over to it."],"options":["Any object in the same room qualifies, even if the person must walk over to it.","It describes how easily the person can physically reach the object.","An object may be within arm’s reach without being held."]},"advanced-native-278-v1-branch":{"type":"mc","answers":["You can see them, but you would need to move closer to pick them up."],"options":["Let us judge reach by visibility alone.","You can see them, but you would need to move closer to pick them up.","Being in the same room is enough, so the distance from your seat does not matter."]},"advanced-native-278-v1-final":{"type":"open","answers":["The picture books are within