('advanced-native-284', '["phrase"]'::jsonb, '{"advanced-native-284-v1-audio":{"type":"mc","answers":["It regularly accompanies ordinary morning activities."],"options":["It plays only during a single planned performance.","It regularly accompanies ordinary morning activities.","It has replaced breakfast preparation as the family’s main daily task.","It provides sound for a film they are recording about one unusual day."]},"advanced-native-284-v2-reply":{"type":"mc","answers":["Its familiar programmes accompany our usual morning routine.","I associate those voices with getting ready to leave home.","We hear it while preparing breakfast most mornings.","It is the soundtrack of everyday life in our kitchen."],"options":["Its familiar programmes accompany our usual morning routine.","I associate those voices with getting ready to leave home.","We hear it while preparing breakfast most mornings.","It is the soundtrack of everyday life in our kitchen."]},"advanced-native-284-v1-scene":{"type":"mc","answers":["The playlist has become the soundtrack of everyday life on my commute."],"options":["The playlist is only a sound effect for a one-off theatre rehearsal.","The playlist is a new recording I have never played during a journey.","The playlist has become the soundtrack of everyday life on my commute."]},"advanced-native-284-v1-contrast":{"type":"mc","answers":["A song is heard once at a special ceremony, with no connection to ordinary routines described."],"options":["A familiar broadcast accompanies breakfast repeatedly.","A song is heard once at a special ceremony, with no connection to ordinary routines described.","A regular playlist becomes closely associated with the journey to work."]},"advanced-native-284-v1-branch":{"type":"mc","answers":["It compares familiar daily music to a film’s accompaniment; no film needs to be made."],"options":["We should leave the familiar kitchen radio out unless it was written for a film.","It compares familiar daily music to a film’s accompaniment; no film needs to be made.","A single concert automatically defines the sounds of the family’s whole routine."]},"advanced-native-284-v1-final":{"type":"open","answers":["Market calls and bicycle bells are the soundtrack of everyday life on my walk to school.","The familiar sounds of stalls opening have become the soundtrack of everyday life in our neighbourhood, even without music."],"options":[]}}'::jsonb),
('advanced-native-285', '["phrase"]'::jsonb, '{"advanced-native-285-v1-audio":{"type":"mc","answers":["They value the garden while remaining open to improvements."],"options":["They value the garden while remaining open to improvements.","They reject suggestions because satisfaction means nothing can change.","They feel ashamed of contributing to the garden.","They are proud only of a private space that neighbours cannot share."]},"advanced-native-285-v2-reply":{"type":"mc","answers":["They feel a positive sense of ownership and care for it.","They are pleased with what they have created together.","They take pride in the shared garden.","They value the garden as a worthwhile community achievement."],"options":["They feel a positive sense of ownership and care for it.","They are pleased with what they have created together.","They take pride in the shared garden.","They value the garden as a worthwhile community achievement."]},"advanced-native-285-v1-scene":{"type":"mc","answers":["They take pride in the magazine while welcoming useful feedback."],"options":["They dismiss the magazine as having no value despite their effort.","They regard reader suggestions as proof that the publication has failed completely.","They take pride in the magazine while welcoming useful feedback."]},"advanced-native-285-v1-contrast":{"type":"mc","answers":["They must regard other people as inferior and refuse all criticism."],"options":["They may put care into how the work is done.","They value the quality or achievement of their work.","They must regard other people as inferior and refuse all criticism."]},"advanced-native-285-v1-branch":{"type":"mc","answers":["We can value our work and still use feedback to improve it."],"options":["We can value our work and still use feedback to improve it.","Ask reviewers only for praise so the group’s pride is not challenged.","Feeling pleased with the draft is enough to conclude that it needs no further checking."]},"advanced-native-285-v1-final"