('advanced-native-286', '["phrase"]'::jsonb, '{"advanced-native-286-v1-audio":{"type":"mc","answers":["People stopped talking and began listening."],"options":["The listeners later recalled the full piece accurately, rather than merely beginning to attend to it.","People stopped talking and began listening.","The audience had already agreed with every point before hearing it.","The rhythm made people leave without noticing the performance."]},"advanced-native-286-v2-reply":{"type":"mc","answers":["It made people pause their conversations and listen.","It caught listeners’ attention.","People noticed the opening and wanted to hear more.","It drew the room’s focus to the performance."],"options":["It made people pause their conversations and listen.","It caught listeners’ attention.","People noticed the opening and wanted to hear more.","It drew the room’s focus to the performance."]},"advanced-native-286-v1-scene":{"type":"mc","answers":["The question caught listeners’ attention at the start."],"options":["The question caught listeners’ attention at the start.","The question settled every listener’s opinion on the topic.","The question went unnoticed while the listeners continued their other conversations."]},"advanced-native-286-v1-contrast":{"type":"mc","answers":["Noticing the opening proves lasting agreement with the whole message."],"options":["Noticing the opening proves lasting agreement with the whole message.","People begin noticing the sound or message.","A distinctive opening may draw interest."]},"advanced-native-286-v1-branch":{"type":"mc","answers":["They started listening; we still need to explain clearly and check what they understood."],"options":["Their attention is enough preparation for the next task, so we can skip the still-needed explanation.","Their interest in the opening lets us report that they understood the whole argument.","They started listening; we still need to explain clearly and check what they understood."]},"advanced-native-286-v1-final":{"type":"open","answers":["The brief pause caught listeners’ attention, and people looked up from their notes to hear what came next.","Silence in the middle of the talk caught listeners’ attention, but it did not tell us whether they agreed with the argument."],"options":[]}}'::jsonb),
('advanced-native-287', '["phrase"]'::jsonb, '{"advanced-native-287-v1-audio":{"type":"mc","answers":["They attended but had little opportunity to make their needs heard."],"options":["They were the only groups given time to speak.","They rejected an equal speaking allocation because they wanted a shorter meeting.","They chose to lead the discussion and set every agenda item.","They attended but had little opportunity to make their needs heard."]},"advanced-native-287-v2-reply":{"type":"mc","answers":["The agenda gave their needs little attention.","They were pushed to the margins of the discussion.","The larger organisations took nearly all the available time.","They had very little speaking time."],"options":["The agenda gave their needs little attention.","They were pushed to the margins of the discussion.","The larger organisations took nearly all the available time.","They had very little speaking time."]},"advanced-native-287-v1-scene":{"type":"mc","answers":["The younger members have been pushed to the margins of decision-making."],"options":["The younger members have been pushed to the margins of decision-making.","The invitation alone shows that they have an equal voice in decisions.","They are setting the agenda and directing the older members’ contributions."]},"advanced-native-287-v1-contrast":{"type":"mc","answers":["A proposal is considered carefully but not chosen, while the group keeps an equal voice."],"options":["A proposal is considered carefully but not chosen, while the group keeps an equal voice.","The agenda regularly leaves a group’s concerns unaddressed.","A group repeatedly receives little time to explain its needs."]},"advanced-native-287-v1-branch":{"type":"mc","answers":["Being present does not show how much time or influence they actually have."],"options":["An invitation is enough evidence that their needs reached the agenda.","Let us use attendance alone to measure influence.","Being present does not show how much time or influence th